SET FOREIGN_KEY_CHECKS=0;
CREATE TABLE `advances` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `client_id` int(10) unsigned NOT NULL,
  `amount` decimal(12,2) NOT NULL,
  `advance_date` date NOT NULL,
  `reference_text` varchar(190) DEFAULT NULL,
  `consumed_at` datetime DEFAULT NULL,
  `receivable_id` int(10) unsigned DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `reversed_at` datetime DEFAULT NULL,
  `reversed_by` int(10) unsigned DEFAULT NULL,
  `reversal_reason` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `fk_adv_client` (`client_id`),
  KEY `fk_adv_rec` (`receivable_id`),
  KEY `fk_advances_reversed_by` (`reversed_by`),
  CONSTRAINT `fk_adv_client` FOREIGN KEY (`client_id`) REFERENCES `clients` (`id`),
  CONSTRAINT `fk_adv_rec` FOREIGN KEY (`receivable_id`) REFERENCES `receivables` (`id`),
  CONSTRAINT `fk_advances_reversed_by` FOREIGN KEY (`reversed_by`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `clients` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(190) NOT NULL,
  `document` varchar(30) DEFAULT NULL,
  `phone` varchar(40) DEFAULT NULL,
  `email` varchar(190) DEFAULT NULL,
  `address` text DEFAULT NULL,
  `status` enum('ativo','inativo') NOT NULL DEFAULT 'ativo',
  `standard_km` decimal(10,2) NOT NULL DEFAULT 0.00,
  `has_contract` tinyint(1) NOT NULL DEFAULT 0,
  `monthly_fee` decimal(12,2) NOT NULL DEFAULT 0.00,
  `extra_visit_fee` decimal(12,2) NOT NULL DEFAULT 0.00,
  `due_day` tinyint(3) unsigned NOT NULL DEFAULT 20,
  `contract_notes` text DEFAULT NULL,
  `notes` text DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_clients_name` (`name`),
  KEY `idx_clients_document` (`document`),
  KEY `idx_clients_status` (`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `discounts` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `client_id` int(10) unsigned NOT NULL,
  `amount` decimal(12,2) NOT NULL,
  `discount_date` date NOT NULL,
  `reference_text` varchar(190) DEFAULT NULL,
  `consumed_at` datetime DEFAULT NULL,
  `receivable_id` int(10) unsigned DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `reversed_at` datetime DEFAULT NULL,
  `reversed_by` int(10) unsigned DEFAULT NULL,
  `reversal_reason` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `fk_dis_client` (`client_id`),
  KEY `fk_dis_rec` (`receivable_id`),
  KEY `fk_discounts_reversed_by` (`reversed_by`),
  CONSTRAINT `fk_dis_client` FOREIGN KEY (`client_id`) REFERENCES `clients` (`id`),
  CONSTRAINT `fk_dis_rec` FOREIGN KEY (`receivable_id`) REFERENCES `receivables` (`id`),
  CONSTRAINT `fk_discounts_reversed_by` FOREIGN KEY (`reversed_by`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `material_purchases` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `material_id` int(10) unsigned NOT NULL,
  `purchase_date` date NOT NULL,
  `supplier` varchar(190) DEFAULT NULL,
  `quantity` decimal(12,2) NOT NULL,
  `total_cost` decimal(12,2) NOT NULL,
  `unit_cost` decimal(12,4) NOT NULL,
  `notes` text DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `fk_material_purchases_material` (`material_id`),
  CONSTRAINT `fk_material_purchases_material` FOREIGN KEY (`material_id`) REFERENCES `materials` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `materials` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `description` varchar(190) NOT NULL,
  `minimum_stock` decimal(12,2) NOT NULL DEFAULT 0.00,
  `notes` text DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_material_desc` (`description`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `payables` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `due_date` date NOT NULL,
  `description` varchar(190) NOT NULL,
  `category` varchar(120) DEFAULT NULL,
  `supplier` varchar(190) DEFAULT NULL,
  `total_amount` decimal(12,2) NOT NULL,
  `payment_method` enum('pix','debito','credito','dinheiro','boleto','transferencia') NOT NULL DEFAULT 'pix',
  `installments` int(10) unsigned NOT NULL DEFAULT 1,
  `current_installment` int(10) unsigned NOT NULL DEFAULT 1,
  `installment_value` decimal(12,2) NOT NULL DEFAULT 0.00,
  `status` enum('pendente','pago') NOT NULL DEFAULT 'pendente',
  `paid_at` date DEFAULT NULL,
  `notes` text DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_payable_due` (`due_date`),
  KEY `idx_payable_supplier` (`supplier`),
  KEY `idx_payable_category` (`category`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `payments` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `receivable_id` int(10) unsigned NOT NULL,
  `payment_date` date NOT NULL,
  `amount` decimal(12,2) NOT NULL,
  `payment_method` enum('pix','debito','credito','dinheiro','boleto','transferencia') NOT NULL DEFAULT 'pix',
  `notes` text DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `reversed_at` datetime DEFAULT NULL,
  `reversed_by` int(10) unsigned DEFAULT NULL,
  `reversal_reason` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `fk_pay_rec` (`receivable_id`),
  KEY `fk_payments_reversed_by` (`reversed_by`),
  CONSTRAINT `fk_pay_rec` FOREIGN KEY (`receivable_id`) REFERENCES `receivables` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_payments_reversed_by` FOREIGN KEY (`reversed_by`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `receivable_payments` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `receivable_id` int(10) unsigned NOT NULL,
  `amount` decimal(12,2) NOT NULL,
  `paid_at` date NOT NULL,
  `created_by` int(10) unsigned DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `reversed_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_payment_receivable` (`receivable_id`,`id`),
  CONSTRAINT `fk_payment_receivable` FOREIGN KEY (`receivable_id`) REFERENCES `receivables` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `receivables` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `client_id` int(10) unsigned NOT NULL,
  `competence` varchar(7) NOT NULL,
  `cycle_start` date NOT NULL,
  `cycle_end` date NOT NULL,
  `due_date` date NOT NULL,
  `due_date_confirmed` tinyint(1) NOT NULL DEFAULT 1,
  `monthly_fee` decimal(12,2) NOT NULL DEFAULT 0.00,
  `services_amount` decimal(12,2) NOT NULL DEFAULT 0.00,
  `materials_amount` decimal(12,2) NOT NULL DEFAULT 0.00,
  `extra_visits_amount` decimal(12,2) NOT NULL DEFAULT 0.00,
  `discount_amount` decimal(12,2) NOT NULL DEFAULT 0.00,
  `advances_amount` decimal(12,2) NOT NULL DEFAULT 0.00,
  `previous_balance` decimal(12,2) NOT NULL DEFAULT 0.00,
  `previous_balance_ref` varchar(100) DEFAULT NULL,
  `previous_balance_competence` varchar(7) DEFAULT NULL,
  `total_amount` decimal(12,2) NOT NULL DEFAULT 0.00,
  `paid_amount` decimal(12,2) NOT NULL DEFAULT 0.00,
  `status` enum('pendente','parcial','pago') NOT NULL DEFAULT 'pendente',
  `closed_at` datetime DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_receivable_client_comp` (`client_id`,`competence`),
  KEY `idx_rec_due` (`due_date`),
  KEY `idx_rec_status` (`status`),
  KEY `idx_rec_closed` (`closed_at`),
  CONSTRAINT `fk_rec_client` FOREIGN KEY (`client_id`) REFERENCES `clients` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `stock_movements` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `material_id` int(10) unsigned NOT NULL,
  `movement_type` enum('entrada','saida','ajuste') NOT NULL,
  `quantity` decimal(12,2) NOT NULL,
  `purchase_id` int(10) unsigned DEFAULT NULL,
  `ticket_id` int(10) unsigned DEFAULT NULL,
  `reference` varchar(190) DEFAULT NULL,
  `notes` text DEFAULT NULL,
  `created_by` int(10) unsigned DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `fk_stock_movements_material` (`material_id`),
  KEY `fk_stock_movements_purchase` (`purchase_id`),
  KEY `fk_stock_movements_ticket` (`ticket_id`),
  KEY `fk_stock_movements_user` (`created_by`),
  CONSTRAINT `fk_stock_movements_material` FOREIGN KEY (`material_id`) REFERENCES `materials` (`id`),
  CONSTRAINT `fk_stock_movements_purchase` FOREIGN KEY (`purchase_id`) REFERENCES `material_purchases` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_stock_movements_ticket` FOREIGN KEY (`ticket_id`) REFERENCES `tickets` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_stock_movements_user` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `system_jobs` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `job_key` varchar(60) NOT NULL,
  `last_run_at` datetime NOT NULL,
  `reference` varchar(20) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_job_key` (`job_key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `ticket_billing_installments` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `ticket_id` int(10) unsigned NOT NULL,
  `charge_type` enum('servico','materiais') NOT NULL,
  `installment_number` int(10) unsigned NOT NULL,
  `installment_count` int(10) unsigned NOT NULL,
  `due_date` date NOT NULL,
  `amount` decimal(12,2) NOT NULL,
  `receivable_id` int(10) unsigned DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `fk_tbi_ticket` (`ticket_id`),
  KEY `fk_tbi_receivable` (`receivable_id`),
  CONSTRAINT `fk_tbi_receivable` FOREIGN KEY (`receivable_id`) REFERENCES `receivables` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_tbi_ticket` FOREIGN KEY (`ticket_id`) REFERENCES `tickets` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `ticket_daily_sequences` (
  `sequence_date` date NOT NULL,
  `last_number` int(11) NOT NULL DEFAULT 0,
  PRIMARY KEY (`sequence_date`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `ticket_materials` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `ticket_id` int(10) unsigned NOT NULL,
  `material_id` int(10) unsigned DEFAULT NULL,
  `description` varchar(190) NOT NULL,
  `quantity` decimal(10,2) NOT NULL DEFAULT 1.00,
  `unit_price` decimal(12,2) NOT NULL DEFAULT 0.00,
  `total_price` decimal(12,2) GENERATED ALWAYS AS (`quantity` * `unit_price`) STORED,
  PRIMARY KEY (`id`),
  KEY `fk_tm_ticket` (`ticket_id`),
  KEY `fk_tm_material` (`material_id`),
  CONSTRAINT `fk_tm_material` FOREIGN KEY (`material_id`) REFERENCES `materials` (`id`),
  CONSTRAINT `fk_tm_ticket` FOREIGN KEY (`ticket_id`) REFERENCES `tickets` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `tickets` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `ticket_number` varchar(20) DEFAULT NULL,
  `occurred_at` datetime NOT NULL,
  `client_id` int(10) unsigned NOT NULL,
  `complainant` varchar(190) DEFAULT NULL,
  `request_text` text NOT NULL,
  `service_type` enum('remoto','presencial','vistoria','preventiva','orcamento') NOT NULL,
  `notes` text DEFAULT NULL,
  `status` enum('aberto','pendente','solucionado','fechado','cancelado') NOT NULL DEFAULT 'aberto',
  `closed_at` datetime DEFAULT NULL,
  `status_changed_at` datetime DEFAULT NULL,
  `locked_at` datetime DEFAULT NULL,
  `solution_text` text DEFAULT NULL,
  `service_description` varchar(255) DEFAULT NULL,
  `service_charged` tinyint(1) NOT NULL DEFAULT 0,
  `service_amount` decimal(12,2) NOT NULL DEFAULT 0.00,
  `extra_visit_amount` decimal(12,2) NOT NULL DEFAULT 0.00,
  `materials_sold` tinyint(1) NOT NULL DEFAULT 0,
  `billed_at` datetime DEFAULT NULL,
  `receivable_id` int(10) unsigned DEFAULT NULL,
  `created_by` int(10) unsigned DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_ticket_number` (`ticket_number`),
  KEY `fk_ticket_user` (`created_by`),
  KEY `idx_ticket_date` (`occurred_at`),
  KEY `idx_ticket_status` (`status`),
  KEY `idx_ticket_client` (`client_id`),
  KEY `idx_ticket_billed` (`billed_at`),
  KEY `fk_ticket_receivable` (`receivable_id`),
  KEY `idx_tickets_closed` (`closed_at`),
  KEY `idx_tickets_locked` (`locked_at`),
  CONSTRAINT `fk_ticket_client` FOREIGN KEY (`client_id`) REFERENCES `clients` (`id`),
  CONSTRAINT `fk_ticket_receivable` FOREIGN KEY (`receivable_id`) REFERENCES `receivables` (`id`),
  CONSTRAINT `fk_ticket_user` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `users` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(120) NOT NULL,
  `email` varchar(190) NOT NULL,
  `password_hash` varchar(255) NOT NULL,
  `role` enum('admin','tecnico','financeiro') NOT NULL DEFAULT 'tecnico',
  `active` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `failed_attempts` int(11) NOT NULL DEFAULT 0,
  `locked_until` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `email` (`email`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
SET FOREIGN_KEY_CHECKS=1;
